# New Hampshire RSA from gc.nh.gov/rsa: NHTOC.htm -> each title's chapter table -> each chapter's merged page (N-mrg.htm, every section of the chapter); text = the section's <codesect>.
import re
BASE = "https://gc.nh.gov/rsa/html/"

def _chapter(url):
    _, html = fetch(url)
    for part in html.split("<h3>Section ")[1:]:
        part = part.split("<h3>")[0]
        sid = part.split("</h3>")[0].strip()
        if " " in sid:                       # "4:9-f to 4:9-h Repealed by ..." — a range of repealed numbers, not a section
            continue
        b = re.search(r"<b>(.*?)</b>", part, re.S)
        heading = block_text('<div id="h">' + (b.group(1) if b else "") + "</div>", id="h").replace("\n", " ")
        heading = re.sub(r"\s*[–\u0096-]\s*$", "", heading[len(sid):].strip() if heading.startswith(sid) else heading).strip()
        c = re.search(r"<codesect>(.*?)</codesect>", part, re.S)
        text = block_text('<div id="t">' + (c.group(1) if c else "") + "</div>", id="t").strip()
        if not text and re.match(r"(?i)(repealed|reserved|expired|renumbered)", heading):
            text = heading                  # "4:6 Repealed by 1985, 399:24, I, eff. July 1, 1985." is the whole entry
        if text:
            yield {"id": sid, "heading": heading, "text": text, "url": url}

def sections():
    _, toc = fetch(BASE + "NHTOC.htm")
    titles = []
    for t in re.findall(r'href="NHTOC/(NHTOC-[A-Z]+)\.htm"', toc):
        if t not in titles:
            titles.append(t)
    log(f"{len(titles)} titles")
    for t in titles:
        try:
            _, page = fetch(f"{BASE}NHTOC/{t}.htm")
        except Exception as e:
            log(f"{t} failed: {e}"); continue
        roman = t.split("-", 1)[1]
        chaps = []
        for c in re.findall(r'href="NHTOC-' + roman + r'-([0-9A-Z-]+)\.htm"', page):
            if c not in chaps:
                chaps.append(c)
        n = 0
        for c in chaps:
            url = f"{BASE}{roman}/{c}/{c}-mrg.htm"     # the merged page the chapter table links, without fetching the table
            try:
                for s in _chapter(url):
                    n += 1
                    yield s
            except Exception as e:
                log(f"chapter {c} failed: {e}")
        log(f"title {roman}: {len(chaps)} chapters, {n} sections")
